user_message:
Compare the typed predicate candidates against the existing registry.
Candidate predicates:
[
  {
    "name": "ENUMERATES_ORDERED_NEXT_STEPS",
    "definition": "The reasoning lays out a numbered or explicitly sequenced set of upcoming operations it intends to perform, forming an executable plan rather than a description of what has already happened.",
    "parameters": [
      {
        "name": "planning_reasoning",
        "type": "reasoning",
        "description": "The agent text that enumerates the upcoming operations and their intended order."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies two or more future operations to be performed.",
      "The operations are presented as a sequence or grouped plan rather than as isolated passing remarks."
    ],
    "exclusion_conditions": [
      "The reasoning only reports operations that were already completed.",
      "The reasoning merely states a general goal without identifying concrete upcoming operations."
    ]
  },
  {
    "name": "RECOVERS_CHECK_WITH_ALTERNATIVE_METHOD",
    "definition": "An observation shows that an information-gathering check produced no usable output, the reasoning attributes this to a limitation of the check's method or tooling instead of to the state of the system, and a follow-up action obtains the same information through a different method.",
    "parameters": [
      {
        "name": "inconclusive_result",
        "type": "observation",
        "description": "The observation reporting an empty, missing, or otherwise unusable result from the original check."
      },
      {
        "name": "method_diagnosis",
        "type": "reasoning",
        "description": "The reasoning explaining which property of the check method caused the unusable result."
      },
      {
        "name": "alternative_action",
        "type": "action",
        "description": "The follow-up action that retrieves the intended information by a different technique."
      }
    ],
    "assertion_conditions": [
      "The observation shows the original check yielded no interpretable information (e.g., empty output) while independent evidence suggests the checked condition is not necessarily absent.",
      "The reasoning identifies a concrete limitation of the original method (such as unsupported syntax, symlink handling, or wrong data format) as the explanation.",
      "The alternative action uses a materially different method aimed at the same information target."
    ],
    "exclusion_conditions": [
      "The reasoning attributes the empty result to an actual defect or absence in the system under test.",
      "The follow-up action repeats the identical method or only cosmetic variations of it.",
      "No reasoning distinguishes a tooling artifact from a genuine negative result."
    ]
  },
  {
    "name": "DISMISSES_ANOMALY_AS_BENIGN",
    "definition": "The reasoning interprets an unexpected or seemingly abnormal artifact visible in the observation, attributes it to an identified benign cause, and explicitly judges it as not indicating failure of the checked condition.",
    "parameters": [
      {
        "name": "interpretive_reasoning",
        "type": "reasoning",
        "description": "The reasoning that explains the anomaly's cause and judges whether it is harmful."
      },
      {
        "name": "anomalous_observation",
        "type": "observation",
        "description": "The observation containing the unusual entry, state, or leftover artifact being explained."
      }
    ],
    "assertion_conditions": [
      "The observation contains content that deviates from the expected clean state (e.g., non-listening socket states, defunct processes, residual entries).",
      "The reasoning names a plausible origin for that content and states that it does not impair the required behavior.",
      "The dismissal is accompanied by, or consistent with, independent evidence that the required behavior still holds."
    ],
    "exclusion_conditions": [
      "The reasoning treats the anomalous content as a fault that must be repaired.",
      "The reasoning ignores the anomalous content instead of explaining it.",
      "The anomaly is dismissed without any stated cause or supporting evidence of normal behavior."
    ]
  },
  {
    "name": "CONFIRMS_RESULT_MATCHES_CRITERION",
    "definition": "The reasoning compares identifiable content of the observation against the previously required success criterion and concludes that the criterion is met (or not met) because of that content.",
    "parameters": [
      {
        "name": "verdict_reasoning",
        "type": "reasoning",
        "description": "The reasoning stating the comparison outcome between the observed result and the success criterion."
      },
      {
        "name": "criterion_observation",
        "type": "observation",
        "description": "The observation whose content supplies the result being judged."
      }
    ],
    "assertion_conditions": [
      "The reasoning references specific observed content (output text, status code, state listing, or similar) rather than the mere fact that an action ran.",
      "The reasoning states explicitly whether the observed content satisfies the required end state."
    ],
    "exclusion_conditions": [
      "The reasoning only restates or paraphrases the observation without judging it against a criterion.",
      "Success is asserted solely because an action was executed or a command exited without the relevant evidence being inspected.",
      "The observation content is unrelated to the criterion being judged."
    ]
  },
  {
    "name": "TESTS_UNCERTAINTY_WITH_PROBE",
    "definition": "The reasoning identifies a specific unresolved doubt about system behavior, a targeted action is aimed at that doubt, and the resulting observation supplies interpretable evidence about it.",
    "parameters": [
      {
        "name": "probe_action",
        "type": "action",
        "description": "The action performing the targeted test of the identified doubt."
      },
      {
        "name": "uncertainty_reasoning",
        "type": "reasoning",
        "description": "The reasoning stating the specific uncertainty or suspicion being investigated."
      },
      {
        "name": "probe_result",
        "type": "observation",
        "description": "The observation reporting the outcome that bears on the stated uncertainty."
      }
    ],
    "assertion_conditions": [
      "The reasoning names a concrete doubt, suspicion, or unverified assumption about system state.",
      "The probe action is directed at obtaining evidence about that specific doubt, not at changing system state generally.",
      "The observation contains a result that can be interpreted as supporting or refuting the doubt."
    ],
    "exclusion_conditions": [
      "The action is routine configuration or setup without an investigative purpose.",
      "The observation does not address the stated doubt.",
      "No identifiable uncertainty motivates the action."
    ]
  },
  {
    "name": "REPRODUCES_STIPULATED_WORKFLOW",
    "definition": "The action executes the exact procedure stipulated by the task or user requirement, mirroring its steps rather than a simplified proxy, in order to validate that the stipulated procedure works as specified.",
    "parameters": [
      {
        "name": "validation_reasoning",
        "type": "reasoning",
        "description": "The reasoning stating that the stipulated procedure itself is being replayed for validation."
      },
      {
        "name": "replay_action",
        "type": "action",
        "description": "The action whose operations reproduce the stipulated steps."
      }
    ],
    "assertion_conditions": [
      "The reasoning states an intention to run the exact sequence that the requester will run.",
      "The action contains the same operations, in the same spirit, as those stipulated rather than an indirect substitute such as a status query."
    ],
    "exclusion_conditions": [
      "The action performs an equivalent-but-different check that does not reproduce the stipulated sequence.",
      "The reasoning does not connect the action to the stipulated procedure.",
      "The action merely inspects configuration without exercising the user-facing workflow."
    ]
  },
  {
    "name": "SELECTS_SUBSTITUTE_APPROACH_UNDER_CONSTRAINT",
    "definition": "The reasoning states an unavailable facility or imposed restriction, weighs possible ways to achieve the same effect, and justifies the approach that the subsequent action implements.",
    "parameters": [
      {
        "name": "constraint_reasoning",
        "type": "reasoning",
        "description": "The reasoning identifying the limitation and justifying the chosen workaround."
      },
      {
        "name": "substitute_action",
        "type": "action",
        "description": "The action implementing the justified approach."
      }
    ],
    "assertion_conditions": [
      "The reasoning explicitly identifies an unavailable tool, capability, or constraint.",
      "The reasoning compares alternatives and explains why the selected approach is acceptable under that constraint.",
      "The substituted action follows the selected approach."
    ],
    "exclusion_conditions": [
      "The reasoning describes the action without any stated constraint motivating the choice.",
      "The action does not correspond to the approach the reasoning justifies.",
      "No alternatives are weighed; the action is merely the only obvious configuration step."
    ]
  },
  {
    "name": "AUDITS_MULTIPLE_INVARIANTS",
    "definition": "The reasoning enumerates several independent conditions that must hold in the final configuration, a single action evaluates those conditions together, and the observation reports distinguishable outcomes for them.",
    "parameters": [
      {
        "name": "checklist_reasoning",
        "type": "reasoning",
        "description": "The reasoning listing the independent conditions the audit must cover."
      },
      {
        "name": "audit_action",
        "type": "action",
        "description": "The action evaluating the listed conditions together."
      },
      {
        "name": "audit_result",
        "type": "observation",
        "description": "The observation reporting per-condition results of the audit."
      }
    ],
    "assertion_conditions": [
      "The reasoning enumerates at least two independent conditions or invariants to be checked.",
      "The audit action covers multiple of those conditions in a single invocation.",
      "The observation reports results that can be attributed to individual conditions."
    ],
    "exclusion_conditions": [
      "Only a single condition is checked.",
      "The observation aggregates results so that individual conditions cannot be distinguished.",
      "The enumerated conditions are not actually probed by the action."
    ]
  },
  {
    "name": "INSTALLS_PREVENTIVE_RECOVERY_MECHANISM",
    "definition": "The reasoning anticipates a possible future failure of a required service and the action installs a best-effort self-healing or restart facility that the task did not explicitly request.",
    "parameters": [
      {
        "name": "anticipation_reasoning",
        "type": "reasoning",
        "description": "The reasoning motivating the addition of a preventive recovery mechanism for anticipated failures."
      },
      {
        "name": "mechanism_action",
        "type": "action",
        "description": "The action creating or wiring in the recovery/restart mechanism."
      }
    ],
    "assertion_conditions": [
      "The reasoning frames the addition as protection against a plausible future failure or restart scenario.",
      "The action creates or registers a mechanism that re-establishes service availability without further intervention.",
      "The mechanism is supplementary to, rather than a requirement of, the stated task."
    ],
    "exclusion_conditions": [
      "The action only starts a service once as part of the explicit configuration.",
      "No reasoning connects the addition to anticipated failure.",
      "The mechanism is a required deliverable of the request rather than an optional safeguard."
    ]
  },
  {
    "name": "RESETS_TO_PRISTINE_STATE_FOR_HANDOFF",
    "definition": "The reasoning explains that the environment should be returned to its initial, empty state so that the recipient's first operations behave without conflicts, and the action removes the artifacts produced during validation.",
    "parameters": [
      {
        "name": "handoff_reasoning",
        "type": "reasoning",
        "description": "The reasoning justifying restoring the initial state before handing over."
      },
      {
        "name": "reset_action",
        "type": "action",
        "description": "The action deleting, emptying, or reverting the artifacts created during the work."
      }
    ],
    "assertion_conditions": [
      "The reasoning states that the environment is being returned to its starting or empty condition for the benefit of subsequent use.",
      "The reset action removes or empties artifacts created during setup and validation.",
      "The action preserves the configured infrastructure that the recipient needs."
    ],
    "exclusion_conditions": [
      "The action deletes validation or setup artifacts for ordinary tidiness without a stated handoff rationale.",
      "The action reverts required configuration rather than only produced data.",
      "The reasoning does not address the state in which the environment is left."
    ]
  }
]

Existing registry:
[
  {
    "name": "PLANS_NEXT_ACTION",
    "definition": "The reasoning explicitly expresses an intended future action or sequence of actions that the agent has not yet performed.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node that states an intended future action or sequence."
      }
    ],
    "assertion_conditions": [
      "The reasoning explicitly identifies at least one intended future action or step.",
      "The intended action is presented as something still to be done rather than as already completed."
    ],
    "exclusion_conditions": [
      "The reasoning only reports or summarizes actions already completed.",
      "The reasoning states a conclusion, diagnosis, or observation summary without expressing future intent."
    ]
  },
  {
    "name": "IDENTIFIES_DEFECT_FROM_OBSERVATION",
